#!/usr/bin/env python3
"""FROZEN experiment harness for the RL hill-climb A/B. Agents do not edit this file (SPEC.md).

    python frozen/harness.py --out runs/<name> [--seed 0] [--budget 600] [--rl rl.py] [--no-score] [--smoke]

One experiment:
  1. seed torch/python; load frozen/pretrain.pt into GPT(vocab, 4, 256, 8) with the 'abs' tokenizer;
     copy rl.py to runs/<name>/source/; hash rl.py, harness.py, score.py, metrics.py, lib/, data/, pretrain.pt
  2. model = rl.run(model, tok, targets, budget_secs, device, seed, log, metrics, paths)
     SIGALRM at budget+45 -> status "timeout"; returning after budget+15 is also a timeout
  3. save final.pt (lib.model.save_ckpt layout + stage/seed/shas); greedy held-out damage check
  4. unless --no-score: frozen/score.py --ckpt final.pt --k 32 --seed 0 (subprocess, same GPU env)
  5. write runs/<name>/summary.json

Env: AB_SCORE_STUB=1 makes the harness call score.py with --local-stub (plumbing tests only; no daemon).
     AB_ARM overrides the arm name (default: basename of the directory that contains frozen/).
"""
import argparse, datetime, hashlib, importlib.util, json, os, random, shutil, signal, subprocess, sys, time, traceback

FROZEN = os.path.dirname(os.path.abspath(__file__))
LIB = os.path.join(FROZEN, 'lib')
DATA = os.path.join(FROZEN, 'data')
for _p in (FROZEN, LIB):
    if _p not in sys.path:
        sys.path.insert(0, _p)
# `import harness` from rl.py must return this module, not a second copy
sys.modules.setdefault('harness', sys.modules[__name__])

import torch  # noqa: E402
from model import GPT  # noqa: E402
from tokenizer import Tokenizer  # noqa: E402
from sample import generate  # noqa: E402
from nd_verify import verify_text  # noqa: E402
from metrics import Metrics  # noqa: E402

N_LAYER, D_MODEL, N_HEAD = 4, 256, 8
TIMEOUT_GRACE = 15          # returning later than budget + this is a timeout
ALARM_GRACE = 45            # SIGALRM at budget + this
HELDOUT_N, HELDOUT_STRIDE = 1000, 5   # heldout_cap6.jsonl is length-ordered (1,000 each of 2..6 lines): every 5th record
GREEDY_BATCH, GREEDY_MAX_NEW = 384, 512
SCORE_K, SCORE_SEED = 32, 0
SMOKE_TARGETS, SMOKE_BUDGET, SMOKE_HELDOUT = 8, 20, 64
SUMS_FILE = 'SHA256SUMS'

_SHAS = {}      # filled by main(); stored in every checkpoint saved through save_checkpoint
_RUN = {}       # stage/seed for save_checkpoint


class Timeout(BaseException):   # BaseException: a bare `except Exception` in rl.py cannot swallow it
    pass


def log(msg):
    print(f'[{time.strftime("%H:%M:%S")}] {msg}', flush=True)


def read_jsonl(fn):
    with open(fn) as f:
        return [json.loads(l) for l in f if l.strip()]


def file_sha256(fn):
    h = hashlib.sha256()
    with open(fn, 'rb') as f:
        for chunk in iter(lambda: f.read(1 << 20), b''):
            h.update(chunk)
    return h.hexdigest()


def data_shas():
    """SHA-256 of every file under data/, cached in data/SHA256SUMS (sha256sum format) when present.
    The cache is ignored if its file list or sizes do not match what is on disk."""
    files = sorted(f for f in os.listdir(DATA) if f != SUMS_FILE and os.path.isfile(os.path.join(DATA, f)))
    sums_path = os.path.join(DATA, SUMS_FILE)
    if os.path.exists(sums_path):
        cached, sizes = {}, {}
        for l in open(sums_path):
            parts = l.split()
            if len(parts) >= 2:
                cached[parts[-1].lstrip('*')] = parts[0]
        if sorted(cached) == files:
            return {f'data/{f}': cached[f] for f in files}
        log(f'{SUMS_FILE} does not match data/ contents; recomputing')
    out = {f: file_sha256(os.path.join(DATA, f)) for f in files}
    try:
        with open(sums_path, 'w') as fh:
            fh.writelines(f'{h}  {f}\n' for f, h in out.items())
    except OSError as e:
        log(f'could not write {sums_path}: {e}')
    return {f'data/{f}': h for f, h in out.items()}


def all_shas(rl_path):
    shas = {'rl.py': file_sha256(rl_path)}
    for f in ('harness.py', 'score.py', 'metrics.py', 'pretrain.pt'):
        shas[f] = file_sha256(os.path.join(FROZEN, f))
    for d, _, fs in os.walk(LIB):
        if '__pycache__' in d:
            continue
        for f in sorted(fs):
            if f.endswith('.pyc'):
                continue
            p = os.path.join(d, f)
            shas[os.path.relpath(p, FROZEN)] = file_sha256(p)
    shas.update(data_shas())
    return dict(sorted(shas.items()))


def arm_root():
    d = os.getcwd()
    while True:
        if os.path.isdir(os.path.join(d, 'frozen')):
            return d
        if os.path.dirname(d) == d:
            return os.getcwd()
        d = os.path.dirname(d)


def save_checkpoint(model, tok, path, stage=None, extra=None):
    """Atomic weight snapshot in lib.model.save_ckpt's layout ({'cfg','state','tok_mode','extra'})
    plus 'stage', 'seed', 'shas'; readable by lib.model.load_ckpt. For rl.py's intermediate checkpoints."""
    path = str(path)
    os.makedirs(os.path.dirname(os.path.abspath(path)), exist_ok=True)
    if stage is None:
        stage = os.path.splitext(os.path.basename(path))[0]
    obj = {'cfg': dict(model.cfg), 'state': {k: v.detach().cpu() for k, v in model.state_dict().items()},
           'tok_mode': tok.mode, 'extra': dict(extra or {}), 'stage': stage, 'seed': _RUN.get('seed'), 'shas': dict(_SHAS)}
    tmp = path + '.tmp'
    torch.save(obj, tmp)
    os.replace(tmp, path)
    return path


def heldout_slice(n=HELDOUT_N):
    recs = read_jsonl(os.path.join(DATA, 'heldout_cap6.jsonl'))
    return recs[::HELDOUT_STRIDE][:n]


def heldout_greedy(model, tok, n=HELDOUT_N, recs=None):
    """Fraction of the fixed held-out cap-6 slice solved by greedy decoding (in-distribution damage check)."""
    recs = recs if recs is not None else heldout_slice(n)
    was_training = model.training
    model.eval()
    outs = generate(model, tok, [r['prompt'] for r in recs], greedy=True, max_new=GREEDY_MAX_NEW, batch=GREEDY_BATCH)
    if was_training:
        model.train()
    ok = sum(verify_text(r['prompt'] + ' ' + p)[0] for r, p in zip(recs, outs))
    return ok / max(len(recs), 1)


def load_pretrained(device):
    tok = Tokenizer('abs')
    ck = torch.load(os.path.join(FROZEN, 'pretrain.pt'), map_location='cpu')
    assert ck.get('tok_mode', 'abs') == 'abs', ck.get('tok_mode')
    model = GPT(tok.vocab_size, N_LAYER, D_MODEL, N_HEAD)
    model.load_state_dict(ck['state'])
    return model.to(device), tok


def import_rl(path):
    spec = importlib.util.spec_from_file_location('rl', path)
    mod = importlib.util.module_from_spec(spec)
    sys.modules['rl'] = mod
    spec.loader.exec_module(mod)
    return mod


def run_score(a, ckpt):
    cmd = [sys.executable, os.path.join(FROZEN, 'score.py'), '--ckpt', ckpt, '--k', str(SCORE_K), '--seed', str(SCORE_SEED),
           '--tag', f'harness:{a.run_name}']
    if a.smoke:
        cmd.append('--smoke')
    if os.environ.get('AB_SCORE_STUB') == '1':
        cmd.append('--local-stub')
    log('scoring: ' + ' '.join(cmd))
    t0 = time.time()
    p = subprocess.run(cmd, env=os.environ.copy(), capture_output=True, text=True, timeout=35 * 60)
    secs = time.time() - t0
    sys.stdout.write(p.stdout)
    sys.stderr.write(p.stderr)
    if p.returncode != 0:
        raise RuntimeError(f'score.py exited {p.returncode}: {(p.stderr or p.stdout).strip()[-1000:]}')
    with open(os.path.join(os.path.dirname(ckpt), 'score.json')) as f:
        return json.load(f), secs, p.stdout.strip().splitlines()[-1] if p.stdout.strip() else ''


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument('--out', required=True)
    ap.add_argument('--seed', type=int, default=0)
    ap.add_argument('--budget', type=float, default=600)
    ap.add_argument('--rl', default='rl.py')
    ap.add_argument('--no-score', action='store_true')
    ap.add_argument('--smoke', action='store_true', help='8 targets, 20 s budget, 16-theorem dev subset')
    a = ap.parse_args()
    T0 = time.time()
    started = datetime.datetime.now(datetime.timezone.utc).strftime('%Y-%m-%dT%H:%M:%SZ')
    if a.smoke:
        a.budget = SMOKE_BUDGET
    out = os.path.abspath(a.out)
    a.run_name = os.path.basename(out.rstrip('/'))
    os.makedirs(os.path.join(out, 'source'), exist_ok=True)
    rl_path = os.path.abspath(a.rl)
    shutil.copy2(rl_path, os.path.join(out, 'source', 'rl.py'))
    arm = os.environ.get('AB_ARM') or os.path.basename(arm_root())

    random.seed(a.seed)
    torch.manual_seed(a.seed)
    device = 'cuda'
    _RUN['seed'] = a.seed
    _SHAS.update(all_shas(rl_path))
    gpu = f"{os.environ.get('CUDA_VISIBLE_DEVICES', '')}:{torch.cuda.get_device_name(0) if torch.cuda.is_available() else 'cpu'}"
    summary = {'status': None, 'metric': None, 'by_len': None, 'rl_secs': None, 'score_secs': None, 'heldout_greedy': None,
               'rl_stats': {}, 'shas': _SHAS, 'seed': a.seed, 'budget': a.budget, 'gpu': gpu, 'started_utc': started,
               'run_name': a.run_name, 'arm': arm, 'smoke': a.smoke, 'out': out}

    def write_summary(status, **kw):
        summary.update(kw)
        summary['status'] = status
        summary['total_secs'] = time.time() - T0
        tmp = os.path.join(out, 'summary.json.tmp')
        with open(tmp, 'w') as f:
            json.dump(summary, f, indent=1)
        os.replace(tmp, os.path.join(out, 'summary.json'))

    metrics = Metrics(out, a.run_name, arm, t0=T0)
    model, tok = load_pretrained(device)
    targets = read_jsonl(os.path.join(DATA, 'targets_L7-9.jsonl'))
    if a.smoke:
        targets = random.Random(a.seed).sample(targets, SMOKE_TARGETS)
    paths = {'targets_extra': os.path.join(DATA, 'targets_extra_L7-9.jsonl'),
             'train_cap6': os.path.join(DATA, 'train_cap6.jsonl'),
             'heldout_cap6': os.path.join(DATA, 'heldout_cap6.jsonl'),
             'out_dir': out, 'save_checkpoint': save_checkpoint, 'heldout_greedy': heldout_greedy, 'smoke': a.smoke}
    log(f'run {arm}/{a.run_name}: seed {a.seed}, budget {a.budget:.0f}s, gpu {gpu}, {len(targets)} targets, '
        f'rl.py {_SHAS["rl.py"][:12]}, harness {_SHAS["harness.py"][:12]}')

    def on_alarm(signum, frame):
        raise Timeout()
    signal.signal(signal.SIGALRM, on_alarm)

    status = 'crash'
    try:
        rl = import_rl(rl_path)
        signal.alarm(int(a.budget + ALARM_GRACE))
        t_rl = time.time()
        try:
            model = rl.run(model, tok, targets, a.budget, device, a.seed, log, metrics, paths)
        finally:
            rl_secs = time.time() - t_rl
            signal.alarm(0)
            summary['rl_secs'] = rl_secs
        summary['rl_stats'] = dict(metrics.summary)
        log(f'rl.run returned after {rl_secs:.1f}s (budget {a.budget:.0f}s)')
        if rl_secs > a.budget + TIMEOUT_GRACE:
            write_summary('timeout', reason=f'rl.run returned after {rl_secs:.1f}s > budget + {TIMEOUT_GRACE}s')
            log('SUMMARY status=timeout')
            return 1
        if not isinstance(model, GPT) or dict(model.cfg) != dict(GPT(tok.vocab_size, N_LAYER, D_MODEL, N_HEAD).cfg):
            raise TypeError(f'rl.run must return the GPT({tok.vocab_size}, {N_LAYER}, {D_MODEL}, {N_HEAD}) model, got {type(model)}')
        model.eval()
        final = save_checkpoint(model, tok, os.path.join(out, 'final.pt'), stage='final')
        th = time.time()
        hg = heldout_greedy(model, tok, recs=heldout_slice(SMOKE_HELDOUT if a.smoke else HELDOUT_N))
        metrics.log(phase='eval', heldout_greedy=hg, source='harness', secs=time.time() - th)
        summary['heldout_greedy'] = hg
        log(f'held-out greedy (final) {hg:.3f} in {time.time() - th:.0f}s')
        if a.no_score:
            write_summary('ok', scored=False)
            log(f'SUMMARY status=ok (not scored) heldout_greedy={hg:.3f}')
            return 0
        write_summary('scoring')   # provisional: lets score.py log the hashes
        del model
        torch.cuda.empty_cache()
        score, score_secs, line = run_score(a, final)
        write_summary('ok', scored=True, metric=score.get('solved'), by_len=score.get('by_len'), score_secs=score_secs,
                      score=score, score_line=line)
        log(f'SUMMARY status=ok metric={score.get("solved")} by_len={score.get("by_len")}')
        return 0
    except Timeout:
        write_summary('timeout', reason=f'SIGALRM at budget + {ALARM_GRACE}s', rl_stats=dict(metrics.summary))
        log('SUMMARY status=timeout (SIGALRM)')
        return 1
    except Exception:
        tb = traceback.format_exc()
        traceback.print_exc()
        write_summary(status, reason=tb[-4000:], rl_stats=dict(metrics.summary))
        log('SUMMARY status=crash')
        return 1


if __name__ == '__main__':
    sys.exit(main())
